//! Refactoring plan: suggestions derived from facts the index already holds.
//!
//! Nothing here is generated by a model. Each suggestion comes from a
//! measurable condition (a long file, a type with many methods, files that
//! depend on each other in a cycle, a function whose collaborators all live in
//! another file), states the evidence, and lists steps in the order that
//! keeps the code compiling between them. The same index always yields the
//! same plan.

use std::collections::{BTreeMap, BTreeSet, HashMap};

use cw_core::{Result, Symbol, SymbolKind};
use cw_graph::{Graph, strongly_connected_components};
use cw_index::Index;
use serde::{Deserialize, Serialize};

use crate::analyze::DEPENDENCY_KINDS;
use crate::gitintel;
use crate::health::{self, MANY_METHODS, PASSIVE_ATTRS};
use crate::rustscan::is_test_path;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Kind {
    /// A file that is long or reaches into many others.
    SplitFile,
    /// A type whose methods fall into separable groups.
    ExtractType,
    /// Files that depend on each other in a loop.
    BreakCycle,
    /// A function that works only with code in another file.
    MoveFunction,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Suggestion {
    pub kind: Kind,
    /// What to change: a file path, a qualified symbol, or the files of a cycle.
    pub target: String,
    /// File to open first.
    pub file: String,
    pub title: String,
    /// 0 to 100; higher pays off sooner.
    pub priority: u32,
    /// The measurements behind the suggestion.
    pub evidence: Vec<String>,
    /// What to do, in order.
    pub steps: Vec<String>,
}

/// Method-name prefixes that describe access, not a responsibility.
const GENERIC_PREFIXES: [&str; 12] = [
    "new", "get", "set", "is", "has", "with", "as", "to", "into", "from", "try", "len",
];
/// Fewest methods sharing a prefix that make a group worth extracting.
const MIN_GROUP: usize = 4;
/// Fewest free functions sharing a prefix that make a module.
const MIN_FUNCTION_GROUP: usize = 3;
/// A type and its methods must span this many lines to earn its own module.
const MIN_CLUSTER_LINES: u32 = 60;
/// Links to another file needed before a function is said to belong there.
const MIN_FOREIGN_LINKS: usize = 3;
const MAX_LISTED: usize = 6;

fn lines_of(symbol: &Symbol) -> u32 {
    symbol.end_line.saturating_sub(symbol.start_line) + 1
}

fn snake(name: &str) -> String {
    let mut out = String::new();
    for (i, c) in name.chars().enumerate() {
        if c.is_uppercase() && i > 0 {
            out.push('_');
        }
        out.extend(c.to_lowercase());
    }
    out
}

fn camel(word: &str) -> String {
    let mut chars = word.chars();
    chars
        .next()
        .map(|first| first.to_uppercase().chain(chars).collect())
        .unwrap_or_default()
}

fn dir_of(file: &str) -> &str {
    file.rsplit_once('/').map_or("", |(dir, _)| dir)
}

fn sibling(file: &str, stem: &str) -> String {
    match dir_of(file) {
        "" => format!("{stem}.rs"),
        dir => format!("{dir}/{stem}.rs"),
    }
}

fn listed(names: &[&str]) -> String {
    let mut text = names
        .iter()
        .take(MAX_LISTED)
        .map(|n| format!("`{n}`"))
        .collect::<Vec<_>>()
        .join(", ");
    if names.len() > MAX_LISTED {
        text.push_str(&format!(" and {} more", names.len() - MAX_LISTED));
    }
    text
}

/// Group names by their first `_`-separated word; groups of at least `min`
/// names, largest first.
fn prefix_groups<'a>(names: &[&'a str], min: usize) -> Vec<(&'a str, Vec<&'a str>)> {
    let mut groups: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for name in names {
        if let Some((prefix, _)) = name.split_once('_')
            && !prefix.is_empty()
            && !GENERIC_PREFIXES.contains(&prefix)
        {
            groups.entry(prefix).or_default().push(name);
        }
    }
    let mut out: Vec<(&str, Vec<&str>)> = groups
        .into_iter()
        .filter(|(_, members)| members.len() >= min)
        .collect();
    out.sort_by(|a, b| b.1.len().cmp(&a.1.len()).then(a.0.cmp(b.0)));
    out
}

/// Facts shared by the detectors.
struct Facts {
    symbols: Vec<Symbol>,
    /// `(source symbol, target symbol)` for every dependency edge between
    /// two indexed symbols.
    links: Vec<(usize, usize)>,
    /// Hotspot score per file, 0 to 100.
    hot: HashMap<String, f64>,
    /// Files that depend on each file, at any distance one hop.
    dependents: HashMap<String, BTreeSet<String>>,
    /// Crate that owns each file, by directory.
    crates: Vec<(String, String)>,
}

impl Facts {
    fn load(index: &Index) -> Result<Self> {
        let mut symbols = index.symbols()?;
        symbols.sort_by(|a, b| a.qualified.cmp(&b.qualified));
        let position: HashMap<&str, usize> = symbols
            .iter()
            .enumerate()
            .map(|(i, s)| (s.qualified.as_str(), i))
            .collect();
        let mut links: Vec<(usize, usize)> = index
            .edges()?
            .iter()
            .filter(|e| DEPENDENCY_KINDS.contains(&e.kind))
            .filter_map(|e| {
                Some((
                    *position.get(e.src.as_str())?,
                    *position.get(e.dst.as_str())?,
                ))
            })
            .filter(|(src, dst)| src != dst)
            .collect();
        links.sort_unstable();
        links.dedup();
        let intel = gitintel::load(index)?;
        let hot = gitintel::hotspots(index, &intel, usize::MAX)?
            .into_iter()
            .map(|h| (h.path, h.score))
            .collect();
        let crates = index
            .crates()?
            .into_iter()
            .map(|c| (c.dir, c.package))
            .collect();
        Ok(Self {
            symbols,
            links,
            hot,
            dependents: gitintel::dependents_by_file(index)?,
            crates,
        })
    }

    fn hotspot(&self, file: &str) -> f64 {
        self.hot.get(file).copied().unwrap_or(0.0)
    }

    fn dependents(&self, file: &str) -> usize {
        self.dependents.get(file).map_or(0, BTreeSet::len)
    }

    fn crate_of(&self, file: &str) -> &str {
        self.crates
            .iter()
            .filter(|(dir, _)| dir.is_empty() || file.starts_with(&format!("{dir}/")))
            .max_by_key(|(dir, _)| dir.len())
            .map_or("", |(_, package)| package.as_str())
    }

    /// Evidence lines every kind shares: churn and reach of `file`.
    fn context(&self, file: &str) -> Vec<String> {
        let mut out = Vec::new();
        let hotspot = self.hotspot(file);
        if hotspot >= 20.0 {
            out.push(format!(
                "hotspot score {hotspot:.1} of 100: it is large and changes often"
            ));
        }
        match self.dependents(file) {
            0 => {}
            n => out.push(format!("{n} other files depend on it directly")),
        }
        out
    }
}

fn priority(base: f64, facts: &Facts, file: &str) -> u32 {
    let reach = (facts.dependents(file) as f64).min(10.0);
    (base + facts.hotspot(file) * 0.3 + reach)
        .round()
        .clamp(0.0, 100.0) as u32
}

fn verify_step(facts: &Facts, file: &str) -> String {
    match facts.crate_of(file) {
        "" => "Run `cargo test` and `cargo clippy --all-targets`.".to_string(),
        package => {
            format!("Run `cargo test -p {package}` and `cargo clippy -p {package} --all-targets`.")
        }
    }
}

/// Long files and files that reach into many others.
fn split_files(index: &Index, facts: &Facts, out: &mut Vec<Suggestion>) -> Result<()> {
    let mut methods: HashMap<&str, Vec<&Symbol>> = HashMap::new();
    for symbol in &facts.symbols {
        if symbol.kind == SymbolKind::Method
            && let Some(parent) = &symbol.parent
        {
            methods.entry(parent.as_str()).or_default().push(symbol);
        }
    }
    for file in health::file_health(index)? {
        if is_test_path(&file.path) {
            continue;
        }
        let find = |detector: &str| file.findings.iter().find(|f| f.detector == detector);
        let (long, fan_out) = (find("long-file"), find("high-fan-out"));
        if long.is_none() && fan_out.is_none() {
            continue;
        }
        let mut evidence: Vec<String> = [long, fan_out, find("long-function")]
            .into_iter()
            .flatten()
            .map(|f| f.message.clone())
            .collect();
        evidence.extend(facts.context(&file.path));

        let items: Vec<&Symbol> = facts
            .symbols
            .iter()
            .filter(|s| s.file == file.path)
            .collect();
        // A type with its methods is the natural unit to move.
        let mut clusters: Vec<(&Symbol, usize, u32)> = items
            .iter()
            .filter(|s| s.kind.is_type())
            .map(|s| {
                let own = methods
                    .get(s.qualified.as_str())
                    .map(Vec::as_slice)
                    .unwrap_or(&[]);
                let lines = lines_of(s) + own.iter().map(|m| lines_of(m)).sum::<u32>();
                (*s, own.len(), lines)
            })
            .filter(|(_, _, lines)| *lines >= MIN_CLUSTER_LINES)
            .collect();
        clusters.sort_by(|a, b| b.2.cmp(&a.2).then(a.0.name.cmp(&b.0.name)));
        let functions: Vec<&str> = items
            .iter()
            .filter(|s| s.kind == SymbolKind::Function)
            .map(|s| s.name.as_str())
            .collect();

        let mut steps = vec![format!(
            "Run the tests that reach `{}` (`get_impacted_tests`) and keep them green after every step.",
            file.path
        )];
        let mut moved = 0;
        // The largest cluster stays; the file keeps its main subject.
        for (symbol, count, lines) in clusters.iter().skip(1).take(3) {
            moved += 1;
            steps.push(format!(
                "Move `{}` with its {count} methods (about {lines} lines) into `{}`.",
                symbol.name,
                sibling(&file.path, &snake(&symbol.name))
            ));
        }
        for (prefix, members) in prefix_groups(&functions, MIN_FUNCTION_GROUP)
            .into_iter()
            .take(3usize.saturating_sub(moved))
        {
            moved += 1;
            steps.push(format!(
                "Move the {} `{prefix}_*` functions ({}) into `{}`.",
                members.len(),
                listed(&members),
                sibling(&file.path, prefix)
            ));
        }
        if moved == 0 {
            steps.push(format!(
                "List the {} items in the file by what they are for; move the largest group that is not the file's main subject into its own module.",
                items.len()
            ));
        }
        if facts.dependents(&file.path) > 0 {
            steps.push(format!(
                "Re-export what moved from `{}` with `pub use`, so the {} files that depend on it compile unchanged.",
                file.path,
                facts.dependents(&file.path)
            ));
            steps.push(
                "Point callers at the new modules one file at a time, then delete the re-exports."
                    .to_string(),
            );
        }
        steps.push(verify_step(facts, &file.path));
        let base = match long.map(|f| f.penalty) {
            Some(2..) => 55.0,
            Some(_) => 40.0,
            None => 30.0,
        };
        out.push(Suggestion {
            kind: Kind::SplitFile,
            title: format!("Split `{}`", file.path),
            priority: priority(base, facts, &file.path),
            target: file.path.clone(),
            file: file.path,
            evidence,
            steps,
        });
    }
    Ok(())
}

/// Types with many methods.
fn extract_types(facts: &Facts, out: &mut Vec<Suggestion>) {
    let mut methods: BTreeMap<&str, Vec<&Symbol>> = BTreeMap::new();
    for symbol in &facts.symbols {
        if symbol.kind == SymbolKind::Method
            && let Some(parent) = &symbol.parent
        {
            methods.entry(parent.as_str()).or_default().push(symbol);
        }
    }
    for owner in &facts.symbols {
        let Some(own) = methods.get(owner.qualified.as_str()) else {
            continue;
        };
        if !owner.kind.is_type()
            || owner.kind == SymbolKind::Trait
            || own.len() < MANY_METHODS
            || is_test_path(&owner.file)
        {
            continue;
        }
        let lines: u32 = own.iter().map(|m| lines_of(m)).sum();
        let names: Vec<&str> = own.iter().map(|m| m.name.as_str()).collect();
        let groups = prefix_groups(&names, MIN_GROUP);
        let mut evidence = vec![format!(
            "`{}` has {} methods over {lines} lines",
            owner.name,
            own.len()
        )];
        for (prefix, members) in groups.iter().take(3) {
            evidence.push(format!(
                "{} methods start with `{prefix}_`: {}",
                members.len(),
                listed(members)
            ));
        }
        evidence.extend(facts.context(&owner.file));

        let mut steps = Vec::new();
        match groups.first() {
            Some((prefix, members)) => {
                let helper = format!("{}{}", owner.name, camel(prefix));
                steps.push(format!(
                    "Find the fields of `{}` that only the `{prefix}_*` methods read or write.",
                    owner.name
                ));
                steps.push(format!(
                    "Create `{helper}` holding those fields, and make it a field of `{}`.",
                    owner.name
                ));
                steps.push(format!(
                    "Move {} onto `{helper}`; leave one-line methods on `{}` that forward to it.",
                    listed(members),
                    owner.name
                ));
                steps.push(format!(
                    "Change callers to use `{helper}` directly, then delete the forwarding methods."
                ));
                if groups.len() > 1 {
                    steps.push(format!(
                        "Repeat for the `{}_*` group if `{}` is still large.",
                        groups[1].0, owner.name
                    ));
                }
            }
            None => {
                steps.push(format!(
                    "For each method of `{}`, note which fields it reads or writes.",
                    owner.name
                ));
                steps.push(
                    "Methods that share fields with each other but not with the rest form the type to extract; create it and move those fields and methods."
                        .to_string(),
                );
                steps.push(format!(
                    "Leave one-line forwarding methods on `{}` until callers use the new type.",
                    owner.name
                ));
            }
        }
        steps.push(verify_step(facts, &owner.file));
        let size = ((own.len() - MANY_METHODS) as f64).min(20.0);
        out.push(Suggestion {
            kind: Kind::ExtractType,
            target: owner.qualified.clone(),
            file: owner.file.clone(),
            title: format!("Extract a type from `{}`", owner.name),
            priority: priority(35.0 + size, facts, &owner.file),
            evidence,
            steps,
        });
    }
}

/// Files that depend on each other through calls, type references or trait
/// implementations. `use` re-exports alone do not count.
fn break_cycles(facts: &Facts, out: &mut Vec<Suggestion>) {
    // (from file, to file) -> the symbol pairs that make the dependency.
    let mut between: BTreeMap<(&str, &str), Vec<(usize, usize)>> = BTreeMap::new();
    for (src, dst) in &facts.links {
        let (from, to) = (
            facts.symbols[*src].file.as_str(),
            facts.symbols[*dst].file.as_str(),
        );
        if from != to && !is_test_path(from) && !is_test_path(to) {
            between.entry((from, to)).or_default().push((*src, *dst));
        }
    }
    let graph = Graph::from_weighted(
        Vec::new(),
        between
            .iter()
            .map(|((from, to), pairs)| (from.to_string(), to.to_string(), pairs.len() as f64)),
    );
    let component = strongly_connected_components(&graph);
    let mut members: BTreeMap<usize, Vec<&str>> = BTreeMap::new();
    for (node, id) in component.iter().enumerate() {
        members
            .entry(*id)
            .or_default()
            .push(graph.nodes[node].as_str());
    }
    for files in members.values().filter(|m| m.len() >= 2) {
        let inside: BTreeSet<&str> = files.iter().copied().collect();
        // The dependency with the fewest references is the cheapest to remove.
        let Some(((from, to), pairs)) = between
            .iter()
            .filter(|((from, to), _)| inside.contains(from) && inside.contains(to))
            .min_by_key(|((from, to), pairs)| (pairs.len(), *from, *to))
        else {
            continue;
        };
        let mut used: Vec<&str> = pairs
            .iter()
            .map(|(_, dst)| facts.symbols[*dst].qualified.as_str())
            .collect();
        used.sort_unstable();
        used.dedup();
        let users: BTreeSet<&str> = pairs
            .iter()
            .map(|(src, _)| facts.symbols[*src].qualified.as_str())
            .collect();
        let users: Vec<&str> = users.into_iter().collect();

        let mut evidence = vec![format!(
            "{} files depend on each other in a loop: {}",
            files.len(),
            listed(files)
        )];
        evidence.push(format!(
            "weakest link: `{from}` uses `{to}` through {} references to {}",
            pairs.len(),
            listed(&used)
        ));
        let hottest = files
            .iter()
            .copied()
            .max_by(|a, b| facts.hotspot(a).total_cmp(&facts.hotspot(b)).then(b.cmp(a)))
            .unwrap_or(from);
        evidence.extend(facts.context(hottest));

        let steps = vec![
            format!(
                "Remove the dependency of `{from}` on `{to}`: it is the smallest in the loop ({} references, from {}).",
                pairs.len(),
                listed(&users)
            ),
            format!(
                "If {} needs nothing else from `{to}`, move it into `{from}` or into a new module both files can depend on.",
                listed(&used)
            ),
            format!(
                "Otherwise invert the call: have `{to}` pass the value or a closure into `{from}`, or put a trait in `{from}` that `{to}` implements."
            ),
            format!(
                "Confirm with `get_dependency_path` that nothing in `{from}` still reaches `{to}`."
            ),
            verify_step(facts, from),
        ];
        let size = (files.len() as f64 * 3.0).min(20.0);
        out.push(Suggestion {
            kind: Kind::BreakCycle,
            target: files.join(", "),
            file: from.to_string(),
            title: format!("Break the dependency loop between {} files", files.len()),
            priority: priority(25.0 + size, facts, hottest),
            evidence,
            steps,
        });
    }
}

/// Free functions that only work with code in one other file.
fn move_functions(facts: &Facts, out: &mut Vec<Suggestion>) {
    // symbol -> counterpart symbols, both directions.
    let mut uses: HashMap<usize, BTreeSet<usize>> = HashMap::new();
    let mut used_by: HashMap<usize, BTreeSet<usize>> = HashMap::new();
    for (src, dst) in &facts.links {
        uses.entry(*src).or_default().insert(*dst);
        used_by.entry(*dst).or_default().insert(*src);
    }
    let empty = BTreeSet::new();
    for (id, function) in facts.symbols.iter().enumerate() {
        let file_name = function.file.rsplit('/').next().unwrap_or("");
        if function.kind != SymbolKind::Function
            || function.name == "main"
            || matches!(file_name, "main.rs" | "build.rs")
            || is_test_path(&function.file)
            || function
                .attrs
                .iter()
                .any(|a| !PASSIVE_ATTRS.contains(&a.as_str()))
        {
            continue;
        }
        let (out_links, in_links) = (
            uses.get(&id).unwrap_or(&empty),
            used_by.get(&id).unwrap_or(&empty),
        );
        let mut per_file: BTreeMap<&str, usize> = BTreeMap::new();
        for other in out_links.iter().chain(in_links) {
            *per_file
                .entry(facts.symbols[*other].file.as_str())
                .or_default() += 1;
        }
        // Any tie to its own file is a reason to stay.
        if per_file.contains_key(function.file.as_str()) {
            continue;
        }
        let Some((home, links)) = per_file
            .iter()
            .max_by_key(|(file, count)| (**count, std::cmp::Reverse(**file)))
            .map(|(file, count)| (*file, *count))
        else {
            continue;
        };
        let elsewhere: usize = per_file.values().sum::<usize>() - links;
        if links < MIN_FOREIGN_LINKS
            || elsewhere * 2 > links
            || is_test_path(home)
            || facts.crate_of(home) != facts.crate_of(&function.file)
        {
            continue;
        }
        let in_home = |set: &BTreeSet<usize>| -> Vec<&str> {
            set.iter()
                .filter(|s| facts.symbols[**s].file == home)
                .map(|s| facts.symbols[*s].name.as_str())
                .collect()
        };
        let (callees, callers) = (in_home(out_links), in_home(in_links));
        let mut evidence = vec![format!(
            "`{}` has {links} links to `{home}` and none to its own file `{}`",
            function.name, function.file
        )];
        if !callees.is_empty() {
            evidence.push(format!("it uses {}", listed(&callees)));
        }
        if !callers.is_empty() {
            evidence.push(format!("it is used by {}", listed(&callers)));
        }
        if elsewhere > 0 {
            evidence.push(format!("{elsewhere} links go to other files"));
        }
        let outside_callers = in_links
            .iter()
            .filter(|s| facts.symbols[**s].file != home)
            .count();
        let mut steps = vec![format!(
            "Move `{}` ({} lines) from `{}` into `{home}`.",
            function.name,
            lines_of(function),
            function.file
        )];
        if outside_callers == 0 {
            steps.push(
                "Every caller is in the new file: make the function private there.".to_string(),
            );
        } else {
            steps.push(format!(
                "Leave `pub use` of it in `{}` for the {outside_callers} callers elsewhere, then update their imports and delete the re-export.",
                function.file
            ));
        }
        steps.push(format!(
            "Drop the imports in `{}` that only this function needed.",
            function.file
        ));
        steps.push(verify_step(facts, home));
        out.push(Suggestion {
            kind: Kind::MoveFunction,
            target: function.qualified.clone(),
            file: function.file.clone(),
            title: format!("Move `{}` to `{home}`", function.name),
            priority: priority(15.0 + (links as f64 * 2.0).min(20.0), facts, &function.file),
            evidence,
            steps,
        });
    }
}

/// Every suggestion, highest priority first.
pub fn plan(index: &Index) -> Result<Vec<Suggestion>> {
    let facts = Facts::load(index)?;
    let mut out = Vec::new();
    split_files(index, &facts, &mut out)?;
    extract_types(&facts, &mut out);
    break_cycles(&facts, &mut out);
    move_functions(&facts, &mut out);
    out.sort_by(|a, b| {
        b.priority
            .cmp(&a.priority)
            .then(a.kind.cmp(&b.kind))
            .then(a.target.cmp(&b.target))
    });
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn groups_names_by_meaningful_prefix() {
        let names = [
            "render_home",
            "render_note",
            "render_index",
            "render_crate",
            "get_a",
            "get_b",
            "get_c",
            "get_d",
            "parse_x",
            "parse_y",
            "parse_z",
            "parse_w",
            "parse_v",
            "run",
            "_hidden",
        ];
        let groups = prefix_groups(&names, 4);
        let summary: Vec<(&str, usize)> = groups.iter().map(|(p, m)| (*p, m.len())).collect();
        // Accessor prefixes say nothing about responsibility.
        assert_eq!(summary, [("parse", 5), ("render", 4)]);
        assert!(prefix_groups(&names, 6).is_empty());
    }

    #[test]
    fn names_new_modules_and_types() {
        assert_eq!(snake("VaultMeta"), "vault_meta");
        assert_eq!(snake("Index"), "index");
        assert_eq!(camel("render"), "Render");
        assert_eq!(camel(""), "");
        assert_eq!(
            sibling("crates/a/src/big.rs", "vault_meta"),
            "crates/a/src/vault_meta.rs"
        );
        assert_eq!(sibling("main.rs", "cli"), "cli.rs");
        assert_eq!(listed(&["a", "b"]), "`a`, `b`");
        let many = ["a", "b", "c", "d", "e", "f", "g", "h"];
        assert_eq!(listed(&many), "`a`, `b`, `c`, `d`, `e`, `f` and 2 more");
    }
}
